/**
 * @jest-environment node
 *
 * The Relic Vault's media manifest (src/data/projects-media.json, GENERATED by scripts/encode-projects.mjs):
 * every exhibit's clips and poster are on Vercel Blob under content-hashed names, AV1 webm before the H.264
 * fallback, and no placeholder ships.
 */

import projectsData from '@/data/projects.json'
import media from '@/data/projects-media.json'

type Entry = {
  w: number
  h: number
  duration: number
  audio: boolean
  placeholder: boolean
  poster: string
  sources: { src: string; type: string }[]
}

const manifest = media as Record<string, Entry>
const ids = projectsData.map((p) => p.id)
/** https://<store>.public.blob.vercel-storage.com/projects/<id>-<sha256, 12 hex>.<ext> */
const onBlob = (id: string, ext: string) =>
  new RegExp(`^https://[a-z0-9]+\\.public\\.blob\\.vercel-storage\\.com/projects/${id}-[0-9a-f]{12}\\.${ext}$`)

describe('projects-media.json', () => {
  it('has an entry for every project and nothing else', () => {
    expect(Object.keys(manifest)).toEqual(ids)
  })

  it.each(ids)('%s: its poster and clips are on Vercel Blob', (id) => {
    const entry = manifest[id]
    expect(entry.poster).toMatch(onBlob(id, 'jpg'))
    expect(entry.sources.map((s) => s.src)).toEqual([expect.stringMatching(onBlob(id, 'webm')), expect.stringMatching(onBlob(id, 'mp4'))])
  })

  it.each(ids)('%s: AV1 webm first, then H.264 mp4', (id) => {
    expect(manifest[id].sources.map((s) => s.type)).toEqual(['video/webm; codecs=av01.0.05M.08', 'video/mp4'])
  })

  it.each(ids)('%s: a sane size and length', (id) => {
    const { w, h, duration, audio } = manifest[id]
    expect(Number.isInteger(w) && Number.isInteger(h)).toBe(true)
    // the long side at 1280 at most, even dimensions for yuv420p
    expect(Math.max(w, h)).toBeLessThanOrEqual(1280)
    expect(Math.min(w, h)).toBeGreaterThanOrEqual(360)
    expect(w % 2 + (h % 2)).toBe(0)
    expect(duration).toBeGreaterThan(2)
    expect(duration).toBeLessThanOrEqual(40)
    expect(typeof audio).toBe('boolean')
  })

  it('ships no placeholder: every clip is encoded from a master', () => {
    expect(ids.filter((id) => manifest[id].placeholder !== false)).toEqual([])
  })

  it('keeps Quadzilla portrait and the rest landscape', () => {
    projectsData.forEach((p) => {
      const { w, h } = manifest[p.id]
      expect(p.id === 'quadzilla' ? h > w : w > h).toBe(true)
    })
  })
})
